'use strict';
const $ = (s,r=document)=>r.querySelector(s);
const $$ = (s,r=document)=>[...r.querySelectorAll(s)];
const esc = v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n=>new Intl.NumberFormat('es-GT',{style:'currency',currency:'GTQ'}).format(Number(n)||0);
const today = ()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Guatemala',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const offsetDate = n=>{const d=new Date(today()+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
const dateLabel = (value,options={day:'numeric',month:'short',year:'numeric'})=>new Date(String(value).slice(0,10)+'T12:00:00').toLocaleDateString('es-GT',options);
const initial = name=>String(name||'Áurea').split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
