const icon = name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;
const sprig=()=>`<svg class="sprig" viewBox="0 0 100 70" fill="none" stroke="currentColor" stroke-width="1.1" aria-hidden="true"><path d="M12 62Q42 32 86 10M28 48Q15 22 41 22Q42 39 28 48M40 38Q39 8 60 5Q61 25 40 38M55 27Q68 4 87 4Q80 24 55 27M34 44Q61 35 72 54Q48 58 34 44M54 29Q78 25 88 42Q68 46 54 29M22 54 10 53"/></svg>`;
const brand=()=>`<div class="brand">${sprig()}<div class="brand-name">ÁUREA</div><div class="brand-tag">Un lugar para quedarse</div></div>`;
let state={mode:'demo',user:null,data:null,page:'inicio',branch:1,query:'',filter:'',date:'',tab:'ingredientes',pageNo:1,register:false,report:null,reportFrom:today().slice(0,7)+'-01',reportTo:today(),global:''};
let toastTimer;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000)}
async function api(path,data){const response=await fetch('/api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});let body;try{body=await response.json()}catch{throw Error('No se pudo comunicar con el servidor.')}if(!response.ok){if(response.status===401){state.user=null;render()}throw Error(body.error||'No se pudo completar la operación.')}return body}
function demoData(){
 const names=[['Valeria','Torres'],['Diego','Ramírez'],['Sofía','Méndez'],['Carlos','Herrera'],['Lucía','Gómez'],['Mariana','López'],['Andrés','Castillo'],['Isabella','Fuentes'],['Javier','Morales'],['Camila','Rivas']];
 const clientes=names.map(([nombre,apellido],i)=>({cliente_id:i+1,nombre,apellido,nit:i===0?'CF':String(1234567+i)+'-0',telefono:String(50234567+i)}));
 const platillos=[['Pasta Alfredo con pollo',65,'Pastas'],['Cappuccino de la casa',24,'Café'],['Croissant de almendra',28,'Panadería'],['Ensalada Áurea',48,'Ensaladas'],['Sándwich de pollo',45,'Sándwiches'],['Cheesecake de frutos rojos',32,'Postres'],['Latte de vainilla',27,'Café'],['Tostadas de aguacate',38,'Desayunos']].map(([nombre_platillo,precio,categoria],i)=>({platillo_id:i+1,nombre_platillo,precio,categoria}));
 const ingredients=[['Pechuga de pollo','kg',5,2],['Crema','L',2,.5],['Champiñones','kg',3,1],['Café en grano','kg',2,8],['Leche','L',5,18],['Pasta','kg',3,12],['Queso parmesano','kg',1,4],['Harina','kg',3,15],['Aguacate','ud',10,30],['Pan artesanal','ud',8,24],['Frutos rojos','kg',1,5],['Azúcar','kg',2,10]];
 const ingredientes=ingredients.map(([nombre_ingrediente,unidad_medida,stock_minimo],i)=>({ingrediente_id:i+1,nombre_ingrediente,unidad_medida,stock_minimo}));
 const sucursales=[{sucursal_id:1,nombre_sucursal:'Zona 10',telefono:'2334-5678',dirreccion:'12 calle 4-35, zona 10, Guatemala',capacidad:80},{sucursal_id:2,nombre_sucursal:'Cayalá',telefono:'2367-8901',dirreccion:'Paseo Cayalá, zona 16, Guatemala',capacidad:60}];
 const mesas=sucursales.flatMap(s=>Array.from({length:s.sucursal_id===1?12:8},(_,i)=>({mesa_id:i+1,sucursal_id:s.sucursal_id,capacidad:i%3===0?6:i%2===0?2:4,estado:i%4===0?'Ocupada':'Disponible'})));
 const lotes=sucursales.flatMap(s=>ingredients.map((v,i)=>({lote_id:`S${s.sucursal_id}-L${String(i+1).padStart(3,'0')}`,ingrediente_id:i+1,sucursal_id:s.sucursal_id,fecha_ingreso:offsetDate(-5),fecha_vencimiento:offsetDate(i===1?3:20+i),cantidad_disponible:v[3]+(s.sucursal_id===2?3:0)})));
 const reservas=names.map((_,i)=>({reserva_id:i+1,cliente_id:i+1,sucursal_id:1,fecha_reserva:today(),hora_reserva:['10:00','11:30','13:00','14:30','19:00','15:00','16:30','18:00','19:30','20:00'][i],estado:i===2?'Pendiente':i===4?'Pendiente':'Confirmada',personas:i%3===0?4:2,duracion_minutos:90,observaciones:''}));
 const asignaciones=reservas.map((r,i)=>({reserva_id:r.reserva_id,mesa_id:[2,4,6,8,10,12,2,4,6,8][i],sucursal_id:1}));
 const visitas=[],ventas=[];
 for(let i=0;i<63;i++){const fecha=offsetDate(-Math.floor(i/9));const cliente_id=i%10+1,sucursal_id=i%4===0?2:1,platillo_id=i%8+1;visitas.push({visita_id:i+1,cliente_id,sucursal_id,fecha,observaciones:i%5===0?'Prefiere una mesa tranquila junto a la ventana.':'Excelente atención.'});ventas.push({venta_id:i+1,visita_id:i+1,cliente_id,sucursal_id,fecha,platillo_id,nombre_platillo:platillos[platillo_id-1].nombre_platillo,cantidad:i%3+1,precio_unitario:platillos[platillo_id-1].precio,total:platillos[platillo_id-1].precio*(i%3+1)})}
 const roles=[{rol_id:1,rol:'Gerente'},{rol_id:2,rol:'Mesero'},{rol_id:3,rol:'Administrador'},{rol_id:4,rol:'Encargado de Inventario'}];
 const personal=[{empleado_id:1,nombre_empleado:'Maya',apellido:'Salazar',rol_id:1,sucursal_id:1,estado:'Activo',fecha_contratacion:'2025-02-15'},{empleado_id:2,nombre_empleado:'Daniel',apellido:'Pérez',rol_id:2,sucursal_id:1,estado:'Activo',fecha_contratacion:'2025-06-01'},{empleado_id:3,nombre_empleado:'Ana',apellido:'Luna',rol_id:4,sucursal_id:2,estado:'Activo',fecha_contratacion:'2026-01-12'}];
 return {clientes,platillos,ingredientes,sucursales,mesas,lotes,reservas,asignaciones,visitas,ventas,roles,personal,preferencias:[{cliente_id:1,platillo_id:1},{cliente_id:1,platillo_id:2},{cliente_id:3,platillo_id:4}],movimientos:[],bitacora:[{bitacora_id:1,fecha_hora:new Date().toISOString(),usuario:'Sistema demo',tabla:'reserva',operacion:'INSERT',anterior:null,nuevo:{reserva_id:1,estado:'Confirmada'}}]};
}
const config={
 clientes:{title:'Clientes',subtitle:'Cada visita es una historia que queremos recordar.',icon:'users',singular:'cliente',pk:'cliente_id',fields:[['nombre','Nombre','text',30],['apellido','Apellido','text',30],['nit','NIT / consumidor final','text',13],['telefono','Teléfono','tel',15]]},
 platillos:{title:'Menú',subtitle:'Los sabores que hacen de Áurea un lugar especial.',icon:'dish',singular:'platillo',pk:'platillo_id',fields:[['nombre_platillo','Nombre del platillo','text',50],['precio','Precio (Q)','number'],['categoria','Categoría','text',15]]},
 ingredientes:{title:'Ingredientes',singular:'ingrediente',pk:'ingrediente_id',fields:[['nombre_ingrediente','Ingrediente','text',30],['unidad_medida','Unidad de medida','select',['kg','g','L','ml','ud']],['stock_minimo','Stock mínimo','number']]},
 lotes:{title:'Lotes de inventario',singular:'lote',pk:'lote_id',fields:[['lote_id','Código de lote','text',13],['ingrediente_id','Ingrediente','relation','ingredientes'],['sucursal_id','Sucursal','relation','sucursales'],['fecha_ingreso','Fecha de ingreso','date'],['fecha_vencimiento','Fecha de vencimiento','date'],['cantidad_disponible','Cantidad disponible','number']]},
 personal:{title:'Personal',subtitle:'El equipo detrás de cada buen momento.',icon:'person',singular:'empleado',pk:'empleado_id',fields:[['nombre_empleado','Nombre','text',30],['apellido','Apellido','text',30],['rol_id','Rol','relation','roles'],['sucursal_id','Sucursal','relation','sucursales'],['fecha_contratacion','Fecha de contratación','date'],['estado','Estado','select',['Activo','Inactivo']]]},
 sucursales:{title:'Sucursales',subtitle:'Una misma esencia, diferentes lugares para encontrarnos.',icon:'store',singular:'sucursal',pk:'sucursal_id',fields:[['nombre_sucursal','Nombre','text',15],['telefono','Teléfono','tel',15],['dirreccion','Dirección','text',100],['capacidad','Capacidad total','integer']]},
 mesas:{title:'Mesas',subtitle:'Un lugar para cada encuentro.',icon:'table',singular:'mesa',pk:'mesa_id',fields:[['mesa_id','Número de mesa','integer'],['sucursal_id','Sucursal','relation','sucursales'],['capacidad','Personas','integer'],['estado','Estado operativo','select',['Disponible','Ocupada','Reservada']]]}
};
const navItems=[['inicio','home','Inicio'],['reservas','calendar','Reservaciones'],['mesas','table','Mesas'],['clientes','users','Clientes'],['platillos','dish','Menú'],['inventario','box','Inventario'],['personal','person','Personal'],['reportes','chart','Reportes'],['sucursales','store','Sucursales'],['bitacora','log','Bitácora']];
const allowed = page=>state.user?.rol==='Administrador'||(!['reportes','bitacora','sucursales','personal'].includes(page)&&!(state.user?.rol==='Mesero'&&page==='inventario'));
const canEdit = key=>state.user?.rol==='Administrador'||(state.user?.rol==='Gerente'&&!['personal','sucursales'].includes(key))||(state.user?.rol==='Mesero'&&['clientes','reservas'].includes(key));
const records = key=>state.data?.[key]||[];
const branchRows = key=>records(key).filter(r=>!state.branch||Number(r.sucursal_id)===Number(state.branch));
const find = (key,id)=>records(key).find(r=>String(r[config[key]?.pk||{reservas:'reserva_id',roles:'rol_id'}[key]])===String(id));
const fullName = id=>{const c=find('clientes',id);return c?`${c.nombre} ${c.apellido}`:'Cliente eliminado'};
const branchName = id=>find('sucursales',id)?.nombre_sucursal||'Todas las sucursales';
const badge = value=>`<span class="badge ${['Confirmada','Disponible','Activo','Completada','En orden'].includes(value)?'green':['Cancelada','Stock bajo','Vencido','Inactivo','Ocupada'].includes(value)?'red':['Pendiente','Reservada','Por caducar'].includes(value)?'amber':'gray'}">${esc(value)}</span>`;
function stockRows(){return records('ingredientes').flatMap(i=>(state.branch?[state.branch]:records('sucursales').map(s=>s.sucursal_id)).map(sid=>{const lots=records('lotes').filter(l=>l.ingrediente_id===i.ingrediente_id&&Number(l.sucursal_id)===Number(sid));const stock=lots.reduce((a,l)=>a+Number(l.cantidad_disponible),0);const expiry=lots.filter(l=>l.cantidad_disponible>0).map(l=>l.fecha_vencimiento).sort()[0];return {...i,sucursal_id:sid,stock,expiry,low:stock<=Number(i.stock_minimo),expiring:!!expiry&&expiry<=offsetDate(7),expired:!!expiry&&expiry<today()}}))}
const alerts = ()=>stockRows().filter(r=>r.low||r.expiring);
function reserveTables(id){return records('asignaciones').filter(r=>r.reserva_id===id).map(r=>r.mesa_id).join(', ')||'—'}
function empty(title='No hay registros',text='Prueba otro filtro o agrega el primer registro.',symbol='search'){return `<div class="empty">${icon(symbol)}<h3>${esc(title)}</h3><p>${esc(text)}</p></div>`}
function table(headers,rows){return rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty()}
const tr = cells=>`<tr>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`;
function card(title,symbol,body,link='',page=''){return `<section class="card"><div class="card-header"><h2>${icon(symbol)}${title}</h2>${link?`<button class="link-btn" data-page="${page}">${link} ${icon('chevron')}</button>`:''}</div>${body}</section>`}
function intro(title,subtitle,buttons=''){return `<div class="page-intro"><div><div class="eyebrow">Áurea · Gestión de cafetería</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${buttons}</div></div>`}
function addButton(key,label){return canEdit(key)?`<button class="btn primary" data-new="${key}">${icon('plus')}${label||'Nuevo '+config[key]?.singular}</button>`:''}
function rowActions(key,r,extra=''){const pk=config[key]?.pk;return `<div class="row-actions">${extra}${canEdit(key)?`<button class="icon-btn" data-edit="${key}" data-id="${esc(r[pk])}" data-branch="${r.sucursal_id||''}" aria-label="Editar ${esc(config[key].singular)}">${icon('edit')}</button>`:''}${state.user.rol==='Administrador'?`<button class="icon-btn" data-delete="${key}" data-id="${esc(r[pk])}" data-branch="${r.sucursal_id||''}" aria-label="Eliminar ${esc(config[key].singular)}">${icon('trash')}</button>`:''}</div>`}
function reservationTable(rows,short=false){return table(short?['Hora','Cliente','Personas']:['Hora','Cliente','Personas','Mesa','Estado',''],rows.map(r=>tr([esc(r.hora_reserva.slice(0,5)),`<button data-client="${r.cliente_id}">${esc(fullName(r.cliente_id))}</button>`,r.personas,...(short?[]:[esc(reserveTables(r.reserva_id)),badge(r.estado),`<button class="icon-btn" data-reservation="${r.reserva_id}" aria-label="Editar reservación">${icon('edit')}</button>`])])))}
function dashboard(){
 const reservations=branchRows('reservas').filter(r=>r.fecha_reserva===today()&&r.estado!=='Cancelada').sort((a,b)=>a.hora_reserva.localeCompare(b.hora_reserva));
 const tables=branchRows('mesas'),available=tables.filter(t=>t.estado==='Disponible').length;
 const sales=branchRows('ventas'),dishCounts={};sales.filter(v=>v.fecha===today()).forEach(v=>dishCounts[v.platillo_id]=(dishCounts[v.platillo_id]||0)+Number(v.cantidad));
 const top=Object.entries(dishCounts).sort((a,b)=>b[1]-a[1])[0];const topDish=top?find('platillos',top[0]):null;
 const low=alerts();const daily=Array.from({length:7},(_,i)=>{const date=offsetDate(i-6);return {date,total:sales.filter(v=>v.fecha===date).reduce((s,v)=>s+Number(v.total),0)}});const max=Math.max(...daily.map(x=>x.total),100);
 const visits={};branchRows('visitas').forEach(v=>visits[v.cliente_id]=(visits[v.cliente_id]||0)+1);const frequent=Object.entries(visits).sort((a,b)=>b[1]-a[1]).slice(0,5);
 return `<section class="hero"><div><div class="eyebrow">El arte de hacerte sentir en casa</div><h1>¡Bienvenida${state.user.nombre.split(' ')[0]==='Maya'?'':state.user.nombre.split(' ')[0]==='Daniel'?'o':''}, ${esc(state.user.nombre.split(' ')[0])}!</h1><p>Aquí empieza otro día lleno de buenos sabores.</p><div class="hero-date">${icon('calendar')}${dateLabel(today(),{weekday:'long',day:'numeric',month:'long',year:'numeric'})} <span>·</span> ${esc(branchName(state.branch))}</div></div><div class="hero-logo">${sprig()}<div class="brand-name">ÁUREA</div><div class="brand-tag">Un lugar para quedarse</div></div></section>
 <div class="section-line"><h2>Así va nuestro día</h2><span>Todo lo que necesitas, en un vistazo</span></div>
 <div class="stats"><div class="stat"><div class="stat-icon">${icon('calendar')}</div><div><div class="stat-label">Reservaciones hoy</div><div class="stat-number">${reservations.length}</div><div class="stat-foot">${reservations.filter(r=>r.estado==='Confirmada').length} confirmadas</div></div></div>
 <button class="stat" data-page="mesas"><div class="stat-icon">${icon('table')}</div><div><div class="stat-label">Mesas disponibles</div><div class="stat-number">${available} <span class="muted" style="font-size:17px">/ ${tables.length}</span></div><div class="progress"><span style="width:${tables.length?available/tables.length*100:0}%"></span></div></div></button>
 <button class="stat" data-page="platillos"><div class="stat-icon">${icon('dish')}</div><div><div class="stat-label">El favorito de hoy</div><div class="stat-number compact">${esc(topDish?.nombre_platillo||'Aún sin ventas')}</div><div class="stat-foot">${top?top[1]+' porciones servidas':'Registra visitas con consumo'}</div></div></button>
 <button class="stat" data-page="${allowed('inventario')?'inventario':'reservas'}"><div class="stat-icon">${icon('box')}</div><div><div class="stat-label">Insumos en alerta</div><div class="stat-number">${state.user.rol==='Mesero'?'—':low.length}</div><div class="stat-foot">${state.user.rol==='Mesero'?'Consulta con tu gerente':low.length?badge('Stock bajo'):'Todo en orden'}</div></div></button></div>
 <div class="dash-grid">${card('Reservaciones de hoy','calendar',reservationTable(reservations.slice(0,5)),'Ver todas','reservas')}
 <section class="card"><div class="card-header"><h2>${icon('chart')}Ventas de la semana</h2><span class="badge gray">Últimos 7 días</span></div><div class="chart"><div class="chart-axis">${[1,.75,.5,.25,0].map(x=>`<span>${x?'Q'+Math.round(max*x).toLocaleString('es-GT'):'0'}</span>`).join('')}</div><div class="chart-plot">${daily.map(d=>`<div class="bar-col"><div class="bar" style="height:${d.total/max*100}%"><span class="tooltip">${money(d.total)}</span></div><label>${dateLabel(d.date,{weekday:'short'}).replace('.','')}</label></div>`).join('')}</div></div></section></div>
 <div class="dash-bottom">${card('Insumos en alerta','box',state.user.rol==='Mesero'?empty('Tu equipo se encarga','El inventario está disponible para gerentes y administradores.','box'):table(['Ingrediente','Stock','Mínimo','Estado'],low.slice(0,4).map(r=>tr([esc(r.nombre_ingrediente),`${r.stock} ${esc(r.unidad_medida)}`,`${r.stock_minimo} ${esc(r.unidad_medida)}`,badge(r.low?'Stock bajo':r.expired?'Vencido':'Por caducar')]))),state.user.rol==='Mesero'?'':'Ver inventario','inventario')}
 ${card('Próximas reservaciones','calendar',reservationTable(reservations.filter(r=>r.hora_reserva.slice(0,5)>=new Date().toLocaleTimeString('en-GB',{timeZone:'America/Guatemala',hour:'2-digit',minute:'2-digit'})).slice(0,5),true),'Ver todas','reservas')}
 ${card('Clientes frecuentes','users',`<div class="rank-list">${frequent.map(([id,n],i)=>`<button class="rank-item" style="width:100%" data-client="${id}"><span class="rank">${i+1}</span><span>${esc(fullName(id))}</span><small>${n} visitas</small></button>`).join('')||empty('Sin visitas','Registra la primera visita.','users')}</div>`,'Ver todos','clientes')}</div>`;
}
function toolbar(options='',withDate=false){return `<div class="toolbar"><label class="search-field">${icon('search')}<input id="local-search" placeholder="Buscar en esta sección…" value="${esc(state.query)}" aria-label="Buscar registros"></label>${withDate?`<input type="date" id="date-filter" value="${esc(state.date)}" aria-label="Filtrar por fecha">`:''}${options?`<select id="status-filter" aria-label="Filtrar por estado"><option value="">Todos los estados</option>${options.split('|').map(v=>`<option ${state.filter===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:''}<button class="btn" data-action="clear">${icon('refresh')}Limpiar filtros</button></div>`}
function paginate(rows){const start=(state.pageNo-1)*12;return {rows:rows.slice(start,start+12),footer:`<div class="table-footer"><span>${rows.length?start+1:0}–${Math.min(start+12,rows.length)} de ${rows.length} registros</span><div><button data-action="prev" ${state.pageNo<=1?'disabled':''}>Anterior</button><span>${state.pageNo}</span><button data-action="next" ${start+12>=rows.length?'disabled':''}>Siguiente</button></div></div>`}}
function match(row){return JSON.stringify(row).toLocaleLowerCase('es').includes(state.query.toLocaleLowerCase('es'))}
function reservationPage(){const rows=branchRows('reservas').filter(r=>match({...r,cliente:fullName(r.cliente_id)})&&(!state.filter||r.estado===state.filter)&&(!state.date||r.fecha_reserva===state.date)).sort((a,b)=>b.fecha_reserva.localeCompare(a.fecha_reserva)||a.hora_reserva.localeCompare(b.hora_reserva));const p=paginate(rows);return intro('Reservaciones','El próximo buen momento comienza con una mesa.',addButton('reservas','Nueva reservación'))+toolbar('Pendiente|Confirmada|Completada|Cancelada',true)+`<section class="card">${table(['Fecha','Hora','Cliente','Sucursal','Personas','Mesas','Estado',''],p.rows.map(r=>tr([esc(dateLabel(r.fecha_reserva)),esc(r.hora_reserva.slice(0,5)),`<button data-client="${r.cliente_id}">${esc(fullName(r.cliente_id))}</button>`,esc(branchName(r.sucursal_id)),r.personas,esc(reserveTables(r.reserva_id)),badge(r.estado),`<button class="icon-btn" data-reservation="${r.reserva_id}" aria-label="Editar reserva">${icon('edit')}</button>`])))}${p.footer}</section>`}
function tablePage(){const rows=branchRows('mesas').filter(r=>match(r)&&(!state.filter||r.estado===state.filter));return intro('Mesas','Organiza la disponibilidad de cada sucursal.',addButton('mesas','Agregar mesa'))+toolbar('Disponible|Ocupada|Reservada')+`<div class="info-strip">${icon('clock')}El estado operativo indica la disponibilidad actual. Al reservar también se comprueban los horarios para evitar cruces.</div><div class="table-map">${rows.map(r=>`<div class="table-tile ${r.estado==='Ocupada'?'occupied':r.estado==='Reservada'?'reserved':''}">${badge(r.estado)}${icon('table')}<h3>Mesa ${r.mesa_id}</h3><p>${r.capacidad} personas · ${esc(branchName(r.sucursal_id))}</p>${rowActions('mesas',r,canEdit('reservas')?`<button class="btn" data-book-table="${r.mesa_id}" data-branch="${r.sucursal_id}">${icon('calendar')}Reservar</button>`:'')}</div>`).join('')||empty()}</div>`}
function clientsPage(){const rows=records('clientes').filter(match);const p=paginate(rows);return intro('Clientes',config.clientes.subtitle,addButton('clientes','Nuevo cliente'))+toolbar()+`<section class="card">${table(['Cliente','NIT','Teléfono','Visitas','Preferencias',''],p.rows.map(r=>{const prefs=records('preferencias').filter(v=>v.cliente_id===r.cliente_id);return tr([`<button class="client-name" data-client="${r.cliente_id}"><span class="avatar">${esc(initial(fullName(r.cliente_id)))}</span><span>${esc(fullName(r.cliente_id))}</span></button>`,esc(r.nit),esc(r.telefono),branchRows('visitas').filter(v=>v.cliente_id===r.cliente_id).length,`${prefs.length} platillos`,rowActions('clientes',r,`<button class="icon-btn" data-client="${r.cliente_id}" aria-label="Ver historial del cliente">${icon('eye')}</button>`)])}))}${p.footer}</section>`}
function menuPage(){const rows=records('platillos').filter(r=>match(r)&&(!state.filter||r.categoria===state.filter));const categories=[...new Set(records('platillos').map(r=>r.categoria))];return intro('Nuestro menú',config.platillos.subtitle,addButton('platillos','Nuevo platillo'))+toolbar()+`<div class="tabs"><button data-category="" class="${!state.filter?'active':''}">Todo el menú</button>${categories.map(c=>`<button data-category="${esc(c)}" class="${state.filter===c?'active':''}">${esc(c)}</button>`).join('')}</div><div class="menu-grid">${rows.map(r=>`<article class="menu-card"><div class="dish-symbol">${icon(r.categoria==='Café'?'coffee':'dish')}</div><div class="eyebrow">${esc(r.categoria)}</div><h3>${esc(r.nombre_platillo)}</h3><p class="muted small">Preparado para disfrutar, servido para quedarse.</p><div class="menu-card-bottom"><span class="price">${money(r.precio)}</span>${rowActions('platillos',r)}</div></article>`).join('')||empty()}</div>`}
function inventoryPage(){const low=alerts(),total=stockRows().length,ratio=total?low.length/total*100:0;let body;
 if(state.tab==='ingredientes'){const rows=stockRows().filter(r=>match(r)&&(!state.filter||(state.filter==='Stock bajo'?r.low:state.filter==='Por caducar'?r.expiring:!r.low&&!r.expiring)));const p=paginate(rows);body=`<section class="card">${table(['Ingrediente','Sucursal','Stock actual','Stock mínimo','Vencimiento próximo','Estado',''],p.rows.map(r=>tr([esc(r.nombre_ingrediente),esc(branchName(r.sucursal_id)),`${r.stock} ${esc(r.unidad_medida)}`,`${r.stock_minimo} ${esc(r.unidad_medida)}`,r.expiry?dateLabel(r.expiry):'Sin lotes',badge(r.low?'Stock bajo':r.expired?'Vencido':r.expiring?'Por caducar':'En orden'),rowActions('ingredientes',r)])))}${p.footer}</section>`}
 else if(state.tab==='lotes'){const rows=branchRows('lotes').filter(r=>match({...r,nombre:find('ingredientes',r.ingrediente_id)?.nombre_ingrediente}));const p=paginate(rows);body=`<section class="card">${table(['Lote','Ingrediente','Sucursal','Ingreso','Vencimiento','Disponible',''],p.rows.map(r=>tr([esc(r.lote_id),esc(find('ingredientes',r.ingrediente_id)?.nombre_ingrediente),esc(branchName(r.sucursal_id)),dateLabel(r.fecha_ingreso),dateLabel(r.fecha_vencimiento),`${r.cantidad_disponible} ${esc(find('ingredientes',r.ingrediente_id)?.unidad_medida)}`,rowActions('lotes',r)])))}${p.footer}</section>`}
 else {const rows=records('movimientos').filter(r=>{const l=find('lotes',r.lote_id);return (!state.branch||Number(l?.sucursal_id)===Number(state.branch))&&match(r)});body=`<section class="card">${table(['Fecha','Lote','Responsable','Tipo','Cantidad','Motivo'],rows.map(r=>tr([dateLabel(r.fecha_hora),esc(r.lote_id),esc(find('personal',r.empleado_id)?.nombre_empleado||'—'),badge(r.tipo_movimiento),r.cantidad,esc(r.motivo)])))}</section>`}
 return intro('Inventario','Cuidamos cada ingrediente, desde su llegada hasta el último plato.',`<button class="btn" data-action="movement">${icon('arrow')}Registrar movimiento</button>${addButton(state.tab==='lotes'?'lotes':'ingredientes')}`)+`<div class="tabs">${[['ingredientes','Existencias e ingredientes'],['lotes','Lotes y caducidad'],['movimientos','Movimientos']].map(([k,v])=>`<button data-tab="${k}" class="${state.tab===k?'active':''}">${v}</button>`).join('')}</div><div class="info-strip ${ratio>=15?'red':''}">${icon(ratio>=15?'alert':'box')}<div><strong>${low.length} de ${total} insumos en alerta (${Math.round(ratio)}%).</strong> ${ratio>=15?'Se alcanzó el umbral de alerta del 15%.':'Umbral de alerta general: 15%.'}<br>Stock bajo: existencias ≤ mínimo. Caducidad próxima: dentro de 7 días. Las alertas individuales siempre permanecen visibles.</div></div>`+toolbar(state.tab==='ingredientes'?'Stock bajo|Por caducar|En orden':'')+body;
}
function genericPage(key){const c=config[key];const rows=(key==='personal'?branchRows(key):records(key)).filter(r=>match(r)&&(!state.filter||r.estado===state.filter));const p=paginate(rows);return intro(c.title,c.subtitle,addButton(key))+toolbar(key==='personal'?'Activo|Inactivo':'')+`<section class="card">${table([...c.fields.map(f=>f[1]),''],p.rows.map(r=>tr([...c.fields.map(([field,label,type,source])=>type==='relation'?esc(relationLabel(source,r[field])):field==='estado'?badge(r[field]):type==='date'?dateLabel(r[field]):esc(r[field])),rowActions(key,r)])))}${p.footer}</section>`}
function auditPage(){const rows=records('bitacora').filter(r=>match(r)&&(!state.filter||r.operacion===state.filter));const p=paginate(rows);return intro('Bitácora de actividad','Cada cambio deja una huella: quién, cuándo y qué se modificó.',`<button class="btn" data-action="export-audit">${icon('download')}Exportar CSV</button>`)+toolbar('INSERT|UPDATE|DELETE')+`<section class="card">${table(['Fecha y hora','Usuario','Tabla','Operación','Detalle'],p.rows.map(r=>tr([esc(new Date(r.fecha_hora).toLocaleString('es-GT',{timeZone:'America/Guatemala'})),esc(r.usuario),esc(r.tabla),badge(r.operacion),`<button class="link-btn" data-audit="${r.bitacora_id}">Ver cambio ${icon('chevron')}</button>`])))}${p.footer}</section><p class="muted small" style="margin-top:12px">Se muestran hasta los 300 cambios más recientes. El historial completo permanece en PostgreSQL.</p>`}
function reportPage(){if(!state.report){setTimeout(loadReports,0);return intro('Reportes','La información que convierte cada día en una mejor decisión.')+empty('Preparando tus reportes…','Consultando la información del período.','chart')}
 const r=state.report;return intro('Reportes','Cinco perspectivas para conocer mejor nuestro negocio.',`<button class="btn" data-action="print">${icon('print')}Imprimir</button><button class="btn" data-action="export-report">${icon('download')}Exportar CSV</button>`)+`<div class="toolbar"><label class="field"><span class="small muted">Desde</span><input type="date" id="report-from" value="${state.reportFrom}" required></label><label class="field"><span class="small muted">Hasta</span><input type="date" id="report-to" value="${state.reportTo}" required></label><button class="btn primary" data-action="run-report">${icon('chart')}Consultar período</button><span class="result-count">${esc(branchName(state.branch))}</span></div><div class="report-grid">${card('<span class="report-num">01</span> Top 10 platillos más vendidos','dish',table(['Platillo','Porciones','Ventas'],r.platos.map(v=>tr([esc(v.nombre),v.cantidad,money(v.total)]))))}${card('<span class="report-num">02</span> Top 10 clientes frecuentes','users',table(['Cliente','Visitas'],r.frecuentes.map(v=>tr([esc(v.nombre),v.visitas]))))}${card('<span class="report-num">03</span> Top 5 reservas y preferencias','heart',table(['Cliente','Reservas','Platos favoritos'],r.preferencias.map(v=>tr([esc(v.nombre),v.reservas,esc(v.preferencias)]))))}${card('<span class="report-num">04</span> Insumos por terminar o caducar','box',table(['Ingrediente / lote','Sucursal','Stock / mínimo','Vencimiento'],r.insumos.map(v=>tr([`${esc(v.nombre)}<br><span class="muted small">${esc(v.lote_id)}</span>`,esc(v.nombre_sucursal),`${v.cantidad_disponible} / ${v.stock_minimo}`,dateLabel(v.fecha_vencimiento)]))))}<section class="card wide"><div class="card-header"><h2>${icon('store')}<span class="report-num">05</span> Comportamiento de sucursales</h2></div>${table(['Sucursal','Reservas','Ventas registradas'],r.sucursales.map(v=>tr([esc(v.nombre),v.reservas,money(v.ventas)])))}</section></div><div class="info-strip" style="margin-top:18px">${icon('log')}Las ventas se obtienen de los consumos registrados en visitas. El reporte de insumos combina el stock actual bajo con lotes que vencen en el período consultado. Para el reporte mensual, selecciona el mes completo.</div>`}
function searchPage(){const q=state.global.toLowerCase();const groups=[['Clientes','clientes',records('clientes').filter(r=>(r.nombre+' '+r.apellido+' '+r.telefono).toLowerCase().includes(q)).map(r=>`<button class="rank-item" style="width:100%" data-client="${r.cliente_id}">${icon('users')}${esc(fullName(r.cliente_id))}</button>`)],['Platillos','platillos',records('platillos').filter(r=>r.nombre_platillo.toLowerCase().includes(q)).map(r=>`<div class="rank-item">${icon('dish')}${esc(r.nombre_platillo)}<small>${money(r.precio)}</small></div>`)],['Reservaciones','reservas',branchRows('reservas').filter(r=>(fullName(r.cliente_id)+' '+r.fecha_reserva+' '+r.reserva_id).toLowerCase().includes(q)).map(r=>`<button class="rank-item" style="width:100%" data-reservation="${r.reserva_id}">${icon('calendar')}${esc(fullName(r.cliente_id))}<small>${dateLabel(r.fecha_reserva)} · ${r.hora_reserva.slice(0,5)}</small></button>`)]];return intro('Resultados de búsqueda',`Buscando «${esc(state.global)}» en tus registros.`)+`<div class="report-grid">${groups.map(([title,page,items])=>card(title,page==='platillos'?'dish':page==='clientes'?'users':'calendar',`<div class="rank-list">${items.join('')||empty('Sin coincidencias','Intenta con otro nombre o fecha.')}</div>`)).join('')}</div>`}
function pageContent(){switch(state.page){case 'inicio':return dashboard();case 'reservas':return reservationPage();case 'mesas':return tablePage();case 'clientes':return clientsPage();case 'platillos':return menuPage();case 'inventario':return inventoryPage();case 'personal':case 'sucursales':return genericPage(state.page);case 'bitacora':return auditPage();case 'reportes':return reportPage();case 'buscar':return searchPage();default:return dashboard()}}
function renderContent(){const el=$('#page-content');if(el)el.innerHTML=pageContent()}
function render(){
 if(!state.user){renderLogin();return}
 $('#app').innerHTML=`<div class="layout"><aside class="sidebar">${brand()}<div class="nav-label">NUESTRO ESPACIO</div><nav class="nav" aria-label="Navegación principal">${navItems.filter(([key])=>allowed(key)).map(([key,symbol,title])=>`<button data-page="${key}" class="${state.page===key?'active':''}" ${state.page===key?'aria-current="page"':''}>${icon(symbol)}${title}${key==='inventario'&&alerts().length?`<span class="count">${alerts().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom">${sprig()}<p>Buen café,<br>mejores momentos.</p><small>HECHO PARA COMPARTIR</small></div></aside><div class="main"><header class="topbar"><button class="hamburger" data-action="menu" aria-label="Abrir menú">${icon('menu')}</button><form class="global-search" id="global-search">${icon('search')}<input id="global-query" aria-label="Buscar clientes, reservaciones y platillos" placeholder="Buscar clientes, reservaciones, platillos…" value="${esc(state.global)}"><kbd>↵</kbd></form><div class="topbar-right"><select class="branch-select" id="branch-select" aria-label="Sucursal"><option value="0" ${state.branch===0?'selected':''}>Todas las sedes</option>${records('sucursales').map(s=>`<option value="${s.sucursal_id}" ${Number(state.branch)===s.sucursal_id?'selected':''}>${esc(s.nombre_sucursal)}</option>`).join('')}</select><button class="notification" data-action="notifications" aria-label="Ver alertas">${icon('bell')}${state.user.rol!=='Mesero'&&alerts().length?`<b>${alerts().length}</b>`:''}</button><button class="user-button" data-action="profile"><div class="avatar">${esc(initial(state.user.nombre))}</div><div><strong>${esc(state.user.nombre)}</strong><small>${esc(state.user.rol)}</small></div>${icon('down')}</button></div></header><main class="content">${state.mode==='demo'?`<div class="demo-banner"><span>Modo demostración · Datos de ejemplo guardados en este navegador</span><button data-action="reset-demo">Restablecer demo</button></div>`:''}<div id="page-content">${pageContent()}</div><footer class="footer"><span>ÁUREA · UN LUGAR PARA QUEDARSE</span><span>${state.mode==='demo'?'Demostración local':'Conectado a PostgreSQL'} · ${esc(state.user.rol)}</span></footer></main></div></div>`;
}
function renderLogin(){const reg=state.register;$('#app').innerHTML=`<main class="login"><section class="login-visual">${brand()}<div class="login-quote"><div class="eyebrow">Bienvenido a nuestro espacio</div><h1>Buenos sabores.<br>Mejores momentos.</h1><p>El cuidado de cada detalle comienza aquí.<br>Un lugar para conectar, compartir y quedarse.</p></div><small>CAFÉ · COCINA · BUENA COMPAÑÍA</small></section><section class="login-panel"><div class="login-box"><div class="eyebrow">Administración Áurea</div><h2>${reg?'Sé parte del equipo':'Qué gusto verte de nuevo'}</h2><p>${reg?'Crea tu cuenta de mesero para comenzar a gestionar las experiencias de nuestros clientes.':'Ingresa a tu espacio de trabajo. Hoy también es un buen día para hacer las cosas con cariño.'}</p><form id="login-form">${reg?'<div class="field"><label for="login-name">Nombre completo</label><input id="login-name" name="nombre" autocomplete="name" maxlength="80" required placeholder="Tu nombre y apellido"></div>':''}<div class="field"><label for="login-email">Correo electrónico</label><input id="login-email" name="correo" type="email" autocomplete="username" maxlength="120" required placeholder="nombre@aurea.gt"></div><div class="field"><label for="login-password">Contraseña</label><input id="login-password" name="password" type="password" autocomplete="${reg?'new-password':'current-password'}" ${reg?'minlength="10"':''} required placeholder="${reg?'Al menos 10 caracteres':'Tu contraseña'}"></div><div id="login-error" class="form-error hidden" role="alert"></div><button class="btn primary" type="submit">${reg?'Crear mi cuenta':'Iniciar sesión'} ${icon('chevron')}</button></form><div class="login-switch">${reg?'¿Ya tienes cuenta?':'¿Primera vez aquí?'} <button data-action="toggle-register">${reg?'Inicia sesión':'Crea tu cuenta'}</button></div>${state.mode==='demo'?`<div class="demo-access"><p>Explora la interfaz con datos de ejemplo.<br>Elige un rol para probar su espacio de trabajo:</p><div class="actions">${['Administrador','Gerente','Mesero'].map(r=>`<button class="btn" data-demo="${r}">${r}</button>`).join('')}</div></div>`:''}<div class="login-note">UN LUGAR PARA TRABAJAR CON CALMA Y PROPÓSITO</div></div></section></main>`}
function modal(title,body,footer='',wide=false){const el=$('#modal');el.classList.toggle('wide',wide);el.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Cerrar">${icon('x')}</button></div>${body}${footer}`;if(!el.open)el.showModal()}
function closeModal(){$('#modal').close()}
function formModal(title,fields,onSubmit,note=''){modal(title,`<form id="editor-form"><div class="modal-body">${note?`<p>${note}</p>`:''}<div class="form-grid">${fields}</div><div id="form-error" role="alert" class="form-error hidden"></div></div><div class="modal-footer"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">${icon('check')}Guardar cambios</button></div></form>`);$('#editor-form').addEventListener('submit',async event=>{event.preventDefault();const button=$('button[type=submit]',event.target);button.disabled=true;try{await onSubmit(Object.fromEntries(new FormData(event.target)));closeModal();await refresh();toast('Cambios guardados correctamente.')}catch(error){$('#form-error').textContent=error.message;$('#form-error').classList.remove('hidden')}finally{button.disabled=false}})}
function relationLabel(key,id){const r=key==='roles'?records(key).find(r=>r.rol_id===Number(id)):find(key,id);return r?.nombre_sucursal||r?.nombre_ingrediente||r?.nombre_platillo||r?.rol||'—'}
function options(items,value){return items.map(([v,label])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(label)}</option>`).join('')}
function field(name,label,type='text',value='',source=null,extra=''){let input;if(type==='relation'){const pk=config[source]?.pk||'rol_id';input=`<select name="${name}" id="f-${name}" required ${extra}><option value="">Seleccionar…</option>${options(records(source).map(r=>[r[pk],relationLabel(source,r[pk])]),value)}</select>`}else if(type==='select'){input=`<select name="${name}" id="f-${name}" required ${extra}>${options(source.map(v=>[v,v]),value)}</select>`}else if(type==='textarea'){input=`<textarea name="${name}" id="f-${name}" ${extra}>${esc(value)}</textarea>`}else{input=`<input id="f-${name}" name="${name}" type="${type==='integer'?'number':type}" value="${esc(value)}" ${type==='integer'?'min="1" step="1"':type==='number'?'min="0" step="0.001"':''} ${typeof source==='number'?`maxlength="${source}"`:''} required ${extra}>`}return `<div class="field ${type==='textarea'?'full':''}"><label for="f-${name}">${label}</label>${input}</div>`}
function editEntity(key,id=null,branch=null){if(!canEdit(key))return toast('Tu rol no permite editar esta sección.');const c=config[key];const row=id===null?{}:key==='mesas'?records(key).find(r=>r.mesa_id===Number(id)&&r.sucursal_id===Number(branch)):find(key,id);if(!row)return toast('El registro ya no existe.');const defaults={sucursal_id:state.branch||1,fecha_ingreso:today(),fecha_contratacion:today(),fecha_vencimiento:offsetDate(30),nit:'CF',estado:'Activo'};formModal(`${id===null?'Nuevo':'Editar'} ${c.singular}`,c.fields.map(([name,label,type,source])=>field(name,label,type,row[name]??defaults[name]??'',source,id!==null&&(name===c.pk||key==='mesas'&&name==='sucursal_id')?'readonly disabled':'')).join(''),async values=>{c.fields.forEach(([name,,type])=>{if(type==='relation'||type==='number'||type==='integer')if(values[name]!==undefined)values[name]=Number(values[name])});if(id!==null){values[c.pk]=row[c.pk];if(key==='mesas')values.sucursal_id=row.sucursal_id}if(state.mode==='postgres')await api('entity',{entity:key,id,data:values});else{if(key==='lotes'&&values.fecha_vencimiento<values.fecha_ingreso)throw Error('El vencimiento debe ser posterior al ingreso.');const before=id===null?null:{...row};if(id===null){if(!values[c.pk])values[c.pk]=Math.max(0,...records(key).map(r=>Number(r[c.pk])||0))+1;if(records(key).some(r=>String(r[c.pk])===String(values[c.pk])&&(key!=='mesas'||r.sucursal_id===values.sucursal_id)))throw Error('Ya existe un registro con ese código.');records(key).push(values)}else Object.assign(row,values);demoAudit(key,id===null?'INSERT':'UPDATE',before,values)}},key==='lotes'?'Para registrar entradas o salidas en un lote existente, utiliza «Registrar movimiento».':'')}
function reservationEditor(id=null,tableId=null,branch=null){const row=id?records('reservas').find(r=>r.reserva_id===Number(id)):null;const r=row||{cliente_id:'',sucursal_id:branch||state.branch||1,fecha_reserva:today(),hora_reserva:'12:00',personas:2,estado:'Confirmada',duracion_minutos:90,observaciones:''};const selected=row?records('asignaciones').filter(a=>a.reserva_id===row.reserva_id).map(a=>a.mesa_id):tableId?[Number(tableId)]:[];
 const fields=`<div class="field full"><label for="f-cliente_id">Cliente</label><select name="cliente_id" id="f-cliente_id" required><option value="">Seleccionar cliente…</option>${options(records('clientes').map(c=>[c.cliente_id,fullName(c.cliente_id)]),r.cliente_id)}</select><small>¿Aún no está registrado? Agrégalo primero en Clientes.</small></div>`+field('sucursal_id','Sucursal','relation',r.sucursal_id,'sucursales')+field('personas','Personas','integer',r.personas)+field('fecha_reserva','Fecha','date',r.fecha_reserva)+field('hora_reserva','Hora','time',r.hora_reserva.slice(0,5))+field('duracion_minutos','Duración (minutos)','integer',r.duracion_minutos,null,'max="480"')+field('estado','Estado','select',r.estado,['Pendiente','Confirmada','Completada','Cancelada'])+`<div class="field full"><label>Mesas asignadas</label><div id="table-choices" class="checkboxes"></div><small>Selecciona una o más mesas. Se verifican capacidad y cruces al guardar.</small></div>`+field('observaciones','Observaciones','textarea',r.observaciones);
 formModal(id?'Editar reservación':'Nueva reservación',fields,async values=>{const mesas=$$('input[name=mesas]:checked',$('#editor-form')).map(el=>Number(el.value));const p={...values,cliente_id:Number(values.cliente_id),sucursal_id:Number(values.sucursal_id),personas:Number(values.personas),duracion_minutos:Number(values.duracion_minutos),mesas};if(id)p.reserva_id=Number(id);if(state.mode==='postgres')await api('reservation',p);else{validateDemoReservation(p);const before=row?{...row}:null;if(row)Object.assign(row,p);else{p.reserva_id=Math.max(0,...records('reservas').map(r=>r.reserva_id))+1;records('reservas').push(p)}state.data.asignaciones=records('asignaciones').filter(a=>a.reserva_id!==p.reserva_id);mesas.forEach(mesa_id=>records('asignaciones').push({reserva_id:p.reserva_id,mesa_id,sucursal_id:p.sucursal_id}));demoAudit('reserva',row?'UPDATE':'INSERT',before,p)}});
 const choices=()=>{$('#table-choices').innerHTML=records('mesas').filter(m=>m.sucursal_id===Number($('#f-sucursal_id').value)).map(m=>`<label class="check-tile"><input type="checkbox" name="mesas" value="${m.mesa_id}" ${selected.includes(m.mesa_id)?'checked':''}>Mesa ${m.mesa_id} · ${m.capacidad} p. ${m.estado==='Ocupada'?'(ocupada)':''}</label>`).join('')||'<span class="muted">No hay mesas en esta sucursal.</span>'};choices();$('#f-sucursal_id').addEventListener('change',choices)}
function validateDemoReservation(p){if(!p.mesas.length)throw Error('Selecciona al menos una mesa.');if(p.duracion_minutos<15||p.duracion_minutos>480)throw Error('La duración debe estar entre 15 y 480 minutos.');let seats=0;const start=new Date(p.fecha_reserva+'T'+p.hora_reserva).getTime(),end=start+p.duracion_minutos*60000;for(const id of p.mesas){const m=records('mesas').find(m=>m.mesa_id===id&&m.sucursal_id===p.sucursal_id);if(!m)throw Error('Mesa inválida.');seats+=m.capacidad;if(!['Pendiente','Confirmada'].includes(p.estado))continue;if(m.estado==='Ocupada')throw Error('La mesa está ocupada. Libérala antes de asignarla.');for(const a of records('asignaciones').filter(a=>a.mesa_id===id&&a.sucursal_id===p.sucursal_id&&a.reserva_id!==p.reserva_id)){const r=records('reservas').find(r=>r.reserva_id===a.reserva_id);if(!['Pendiente','Confirmada'].includes(r?.estado))continue;const rs=new Date(r.fecha_reserva+'T'+r.hora_reserva).getTime();if(rs<end&&rs+r.duracion_minutos*60000>start)throw Error('Ya existe una reserva para esa mesa en ese horario.')}}if(seats<p.personas)throw Error('La capacidad de las mesas es insuficiente.')}
function movementEditor(){const lots=branchRows('lotes');const fields=`<div class="field full"><label for="f-lote_id">Lote</label><select name="lote_id" id="f-lote_id" required>${options(lots.map(l=>[l.lote_id,`${l.lote_id} · ${relationLabel('ingredientes',l.ingrediente_id)} · ${l.cantidad_disponible} disponibles`]),'')}</select></div>`+field('empleado_id','Responsable','select','',[])+field('tipo_movimiento','Tipo de movimiento','select','Entrada',['Entrada','Salida','Merma','Ajuste'])+field('cantidad','Cantidad','number',1,null,'min="0.001"')+field('motivo','Motivo','text','',50)+`<p class="muted small" style="grid-column:1/-1">Entrada suma existencias; salida y merma restan. Ajuste establece el saldo exacto indicado.</p>`;
 formModal('Registrar movimiento',fields,async p=>{p.cantidad=Number(p.cantidad);p.empleado_id=Number(p.empleado_id);if(state.mode==='postgres')await api('movement',p);else{const l=find('lotes',p.lote_id);if(!l)throw Error('Selecciona un lote.');const before={...l};const newValue=p.tipo_movimiento==='Ajuste'?p.cantidad:Number(l.cantidad_disponible)+(p.tipo_movimiento==='Entrada'?p.cantidad:-p.cantidad);if(newValue<0)throw Error('No hay existencias suficientes.');l.cantidad_disponible=newValue;records('movimientos').unshift({...p,movimiento_id:records('movimientos').length+1,fecha_hora:new Date().toISOString()});demoAudit('lote_inventario','UPDATE',before,{...l})}});
 const employees=()=>{const sid=find('lotes',$('#f-lote_id').value)?.sucursal_id;$('#f-empleado_id').innerHTML=options(records('personal').filter(e=>e.sucursal_id===sid&&e.estado==='Activo').map(e=>[e.empleado_id,e.nombre_empleado+' '+e.apellido]),'')};employees();$('#f-lote_id').addEventListener('change',employees)}
function clientDetail(id){const c=find('clientes',id);if(!c)return;const preferences=records('preferencias').filter(p=>p.cliente_id===c.cliente_id);const visits=branchRows('visitas').filter(v=>v.cliente_id===c.cliente_id).sort((a,b)=>b.fecha.localeCompare(a.fecha));const reservations=branchRows('reservas').filter(v=>v.cliente_id===c.cliente_id);modal(esc(fullName(c.cliente_id)),`<div class="modal-body"><div class="details-grid"><div class="details-block"><h3>Su espacio en Áurea</h3><p><span class="muted">NIT:</span> ${esc(c.nit)}</p><p><span class="muted">Teléfono:</span> ${esc(c.telefono)}</p><p>${visits.length} visitas · ${reservations.length} reservaciones</p><button class="btn primary" data-visit="${c.cliente_id}">${icon('plus')}Registrar visita / consumo</button></div><div class="details-block"><h3>Sus favoritos</h3><div class="preference-tags">${preferences.map(p=>`<button data-remove-pref="${p.platillo_id}" data-client-id="${c.cliente_id}" title="Quitar preferencia">${esc(relationLabel('platillos',p.platillo_id))} ×</button>`).join('')||'<p class="muted small">Sin preferencias registradas.</p>'}</div><button class="link-btn" data-add-pref="${c.cliente_id}">${icon('plus')}Agregar preferencia</button></div></div><div class="detail-history"><h3>Historial de visitas</h3>${table(['Fecha','Sucursal','Observaciones'],visits.map(v=>tr([dateLabel(v.fecha),esc(branchName(v.sucursal_id)),esc(v.observaciones)])))}</div><div class="detail-history"><h3>Historial de reservaciones</h3>${table(['Fecha','Hora','Mesa','Estado'],reservations.map(r=>tr([dateLabel(r.fecha_reserva),esc(r.hora_reserva.slice(0,5)),esc(reserveTables(r.reserva_id)),badge(r.estado)])))}</div></div>`,`<div class="modal-footer"><button class="btn" data-action="close-modal">Cerrar</button></div>`,true)}
function visitEditor(id){formModal('Registrar visita y consumo',field('sucursal_id','Sucursal','relation',state.branch||1,'sucursales')+field('fecha','Fecha de visita','date',today())+`<div class="field"><label for="f-platillo_id">Platillo consumido (opcional)</label><select name="platillo_id" id="f-platillo_id"><option value="">Visita sin consumo registrado</option>${options(records('platillos').map(p=>[p.platillo_id,p.nombre_platillo+' · '+money(p.precio)]),'')}</select></div>`+field('cantidad','Cantidad','integer',1)+field('observaciones','Experiencia y observaciones','textarea',''),async p=>{p.cliente_id=Number(id);p.sucursal_id=Number(p.sucursal_id);p.cantidad=Number(p.cantidad);p.platillo_id=Number(p.platillo_id)||null;if(state.mode==='postgres')await api('visit',p);else{const v={...p,visita_id:Math.max(0,...records('visitas').map(v=>v.visita_id))+1};records('visitas').push(v);if(p.platillo_id){const dish=find('platillos',p.platillo_id);records('ventas').push({...v,venta_id:records('ventas').length+1,nombre_platillo:dish.nombre_platillo,precio_unitario:dish.precio,total:dish.precio*p.cantidad})}demoAudit('visita','INSERT',null,v)}})}
function preferenceEditor(id){formModal('Agregar plato favorito',field('platillo_id','Platillo','relation','','platillos'),async p=>{p.cliente_id=Number(id);p.platillo_id=Number(p.platillo_id);if(state.mode==='postgres')await api('preference',p);else if(!records('preferencias').some(r=>r.cliente_id===p.cliente_id&&r.platillo_id===p.platillo_id)){records('preferencias').push(p);demoAudit('preferencia','INSERT',null,p)}})}
function demoAudit(table,operation,before,after){records('bitacora').unshift({bitacora_id:Math.max(0,...records('bitacora').map(r=>r.bitacora_id))+1,fecha_hora:new Date().toISOString(),usuario:state.user.correo,tabla:table,operacion:operation,anterior:before,nuevo:after});saveDemo()}
function saveDemo(){try{localStorage.setItem('aurea-demo-v1',JSON.stringify(state.data))}catch{toast('El navegador no permite guardar los cambios de demostración.')}}
async function refresh(){if(state.mode==='postgres')state.data=await api('data');state.report=null;render()}
function deleteEntity(key,id,branch){const c=config[key],r=key==='mesas'?records(key).find(r=>r.mesa_id===Number(id)&&r.sucursal_id===Number(branch)):find(key,id);modal('Eliminar '+c.singular,`<div class="modal-body"><p>¿Quieres eliminar este registro? Si tiene información relacionada, primero deberás resolver esas relaciones.</p><div class="activity-json">${esc(JSON.stringify(r,null,2))}</div><div id="delete-error" class="form-error hidden" role="alert"></div></div>`,`<div class="modal-footer"><button class="btn" data-action="close-modal">Cancelar</button><button class="btn danger" id="confirm-delete">Eliminar registro</button></div>`);$('#confirm-delete').onclick=async()=>{try{if(state.mode==='postgres')await api('delete',{entity:key,id,sucursal_id:Number(branch)});else{const refs={clientes:[['reservas','cliente_id'],['visitas','cliente_id'],['preferencias','cliente_id']],platillos:[['ventas','platillo_id'],['preferencias','platillo_id']],ingredientes:[['lotes','ingrediente_id']],sucursales:[['mesas','sucursal_id'],['reservas','sucursal_id'],['lotes','sucursal_id'],['personal','sucursal_id']],lotes:[['movimientos','lote_id']],personal:[['movimientos','empleado_id']],mesas:[['asignaciones','mesa_id']]};if((refs[key]||[]).some(([table,f])=>records(table).some(v=>String(v[f])===String(id)&&(key!=='mesas'||v.sucursal_id===Number(branch)))))throw Error('Este registro tiene información relacionada y no puede eliminarse.');state.data[key]=records(key).filter(v=>v!==r);demoAudit(key,'DELETE',r,null)}closeModal();await refresh();toast('Registro eliminado.')}catch(e){$('#delete-error').textContent=e.message;$('#delete-error').classList.remove('hidden')}}}
function demoReports(){const from=state.reportFrom,to=state.reportTo;const inRange=r=>r.fecha>=from&&r.fecha<=to;const sales=branchRows('ventas').filter(inRange),visits=branchRows('visitas').filter(inRange);const reservations=branchRows('reservas').filter(r=>r.fecha_reserva>=from&&r.fecha_reserva<=to&&r.estado!=='Cancelada');const dishes={},frequent={},resCounts={};sales.forEach(v=>{const d=dishes[v.platillo_id]||{nombre:v.nombre_platillo,cantidad:0,total:0};d.cantidad+=Number(v.cantidad);d.total+=Number(v.total);dishes[v.platillo_id]=d});visits.forEach(v=>frequent[v.cliente_id]=(frequent[v.cliente_id]||0)+1);reservations.forEach(v=>resCounts[v.cliente_id]=(resCounts[v.cliente_id]||0)+1);return {platos:Object.values(dishes).sort((a,b)=>b.cantidad-a.cantidad).slice(0,10),frecuentes:Object.entries(frequent).sort((a,b)=>b[1]-a[1]).slice(0,10).map(([id,visitas])=>({nombre:fullName(id),visitas})),preferencias:Object.entries(resCounts).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([id,reservas])=>({nombre:fullName(id),reservas,preferencias:records('preferencias').filter(p=>String(p.cliente_id)===id).map(p=>relationLabel('platillos',p.platillo_id)).join(', ')||'Sin preferencias'})),insumos:branchRows('lotes').filter(l=>stockRows().find(s=>s.ingrediente_id===l.ingrediente_id&&s.sucursal_id===l.sucursal_id)?.low||(l.cantidad_disponible>0&&l.fecha_vencimiento>=from&&l.fecha_vencimiento<=to)).map(l=>({...l,nombre:relationLabel('ingredientes',l.ingrediente_id),nombre_sucursal:branchName(l.sucursal_id),stock_minimo:find('ingredientes',l.ingrediente_id)?.stock_minimo})),sucursales:records('sucursales').filter(s=>!state.branch||s.sucursal_id===state.branch).map(s=>({nombre:s.nombre_sucursal,reservas:reservations.filter(r=>r.sucursal_id===s.sucursal_id).length,ventas:sales.filter(r=>r.sucursal_id===s.sucursal_id).reduce((n,v)=>n+Number(v.total),0)})).sort((a,b)=>b.reservas-a.reservas||b.ventas-a.ventas)}}
let reportLoading=false;
async function loadReports(){if(reportLoading||state.page!=='reportes')return;reportLoading=true;try{if(state.reportFrom>state.reportTo)throw Error('La fecha inicial debe ser anterior a la fecha final.');state.report=state.mode==='postgres'?await api('reports',{desde:state.reportFrom,hasta:state.reportTo,sucursal_id:state.branch}):demoReports();renderContent()}catch(e){toast(e.message);$('#page-content').innerHTML=intro('Reportes','No se pudo consultar el período.')+`<button class="btn" data-action="reload">Reintentar</button>`}finally{reportLoading=false}}
function csvDownload(name,rows){if(!rows.length)return toast('No hay datos para exportar.');const headers=[...new Set(rows.flatMap(Object.keys))];const cell=v=>{let s=typeof v==='object'&&v!==null?JSON.stringify(v):String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const csv='\ufeff'+[headers.map(cell).join(','),...rows.map(row=>headers.map(h=>cell(row[h])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function navigate(page){if(page!=='buscar'&&!allowed(page))return toast('Tu rol no tiene acceso a esta sección.');state.page=page;state.query='';state.filter='';state.date='';state.pageNo=1;render();window.scrollTo(0,0)}
document.addEventListener('click',async event=>{
 const el=event.target.closest('button');if(!el)return;const d=el.dataset;
 try{
 if(d.page)return navigate(d.page);
 if(d.demo){state.mode='demo';state.user={nombre:d.demo==='Mesero'?'Daniel Pérez':'Maya Salazar',correo:'demo@aurea.gt',rol:d.demo};try{state.data=JSON.parse(localStorage.getItem('aurea-demo-v1'))||demoData()}catch{state.data=demoData()}state.page='inicio';render();return}
 if(d.new){if(d.new==='reservas')reservationEditor();else editEntity(d.new);return}
 if(d.edit){editEntity(d.edit,d.id,d.branch);return}
 if(d.delete){deleteEntity(d.delete,d.id,d.branch);return}
 if(d.reservation){reservationEditor(Number(d.reservation));return}
 if(d.bookTable){reservationEditor(null,d.bookTable,Number(d.branch));return}
 if(d.client){clientDetail(d.client);return}
 if(d.visit){visitEditor(d.visit);return}
 if(d.addPref){preferenceEditor(d.addPref);return}
 if(d.removePref){const p={cliente_id:Number(d.clientId),platillo_id:Number(d.removePref),remove:true};if(state.mode==='postgres')await api('preference',p);else{const before=records('preferencias').find(r=>r.cliente_id===p.cliente_id&&r.platillo_id===p.platillo_id);state.data.preferencias=records('preferencias').filter(r=>r!==before);demoAudit('preferencia','DELETE',before,null)}await refresh();clientDetail(p.cliente_id);return}
 if(d.audit){const row=records('bitacora').find(r=>r.bitacora_id===Number(d.audit));modal('Detalle del cambio',`<div class="modal-body"><p>${esc(row.tabla)} · ${esc(row.operacion)} · ${esc(row.usuario)}</p><div class="details-grid"><div><h3>Antes</h3><pre class="activity-json">${esc(JSON.stringify(row.anterior,null,2))}</pre></div><div><h3>Después</h3><pre class="activity-json">${esc(JSON.stringify(row.nuevo,null,2))}</pre></div></div></div>`,'',true);return}
 if(d.tab){state.tab=d.tab;state.query='';state.filter='';state.pageNo=1;renderContent();return}
 if(Object.hasOwn(d,'category')){state.filter=d.category;renderContent();return}
 switch(d.action){
 case 'close-modal':closeModal();break;
 case 'toggle-register':state.register=!state.register;renderLogin();break;
 case 'menu':$('.sidebar').classList.toggle('open');break;
 case 'clear':state.query='';state.filter='';state.date='';state.pageNo=1;renderContent();break;
 case 'prev':state.pageNo--;renderContent();break;
 case 'next':state.pageNo++;renderContent();break;
 case 'movement':movementEditor();break;
 case 'print':window.print();break;
 case 'reload':await refresh();break;
 case 'export-audit':csvDownload('aurea-bitacora.csv',records('bitacora').filter(match));break;
 case 'export-report':csvDownload('aurea-reportes.csv',Object.entries(state.report).flatMap(([reporte,rows])=>rows.map(r=>({reporte,...r}))));break;
 case 'run-report':{const from=$('#report-from').value,to=$('#report-to').value;if(!from||!to||from>to)return toast('Selecciona un rango de fechas válido.');state.reportFrom=from;state.reportTo=to;state.report=null;await loadReports();break}
 case 'notifications':{if(state.user.rol==='Mesero'){modal('Tus reservaciones',`<div class="modal-body"><p>Consulta las reservaciones de hoy en la sección Reservaciones.</p></div>`,`<div class="modal-footer"><button class="btn primary" data-page="reservas" onclick="document.querySelector('#modal').close()">Ver reservaciones</button></div>`);break}const rows=alerts();modal('Cuidemos nuestros insumos',`<div class="modal-body"><p>${rows.length} ingredientes requieren atención.</p>${table(['Ingrediente','Sucursal','Estado'],rows.map(r=>tr([esc(r.nombre_ingrediente),esc(branchName(r.sucursal_id)),badge(r.low?'Stock bajo':r.expired?'Vencido':'Por caducar')])))}</div>`);break}
 case 'profile':modal('Tu espacio de trabajo',`<div class="modal-body"><p><strong>${esc(state.user.nombre)}</strong><br>${esc(state.user.correo)}<br>${esc(state.user.rol)} · ${state.mode==='demo'?'Demostración':'PostgreSQL'}</p><p>Los permisos de cada sección corresponden a tu rol.</p></div>`,`<div class="modal-footer"><button class="btn danger" data-action="logout">${icon('logout')}Cerrar sesión</button></div>`);break;
 case 'logout':if(state.mode==='postgres')await api('logout',{});state.user=null;state.report=null;state.register=false;closeModal();render();break;
 case 'reset-demo':modal('Restablecer demostración',`<div class="modal-body"><p>Se reemplazarán los cambios de la demostración por los datos de ejemplo originales.</p></div>`,`<div class="modal-footer"><button class="btn" data-action="close-modal">Cancelar</button><button class="btn primary" data-action="confirm-reset">Restablecer</button></div>`);break;
 case 'confirm-reset':state.data=demoData();saveDemo();state.report=null;closeModal();render();toast('Demostración restablecida.');break;
 }
 }catch(error){toast(error.message)}
});
document.addEventListener('input',event=>{if(event.target.id==='local-search'){const cursor=event.target.selectionStart;state.query=event.target.value;state.pageNo=1;renderContent();const input=$('#local-search');input.focus();input.setSelectionRange(cursor,cursor)}});
document.addEventListener('change',event=>{switch(event.target.id){case 'branch-select':state.branch=Number(event.target.value);state.pageNo=1;state.report=null;render();break;case 'date-filter':state.date=event.target.value;state.pageNo=1;renderContent();break;case 'status-filter':state.filter=event.target.value;state.pageNo=1;renderContent();break}});
document.addEventListener('submit',async event=>{if(event.target.id==='global-search'){event.preventDefault();const query=$('#global-query').value.trim();if(!query)return;state.global=query;navigate('buscar')}if(event.target.id==='login-form'){event.preventDefault();const button=$('button[type=submit]',event.target);button.disabled=true;const p=Object.fromEntries(new FormData(event.target));try{if(state.mode==='demo'){if(state.register){const accounts=JSON.parse(localStorage.getItem('aurea-demo-accounts')||'[]');if(accounts.some(a=>a.correo===p.correo.toLowerCase()))throw Error('Este correo ya está registrado en la demo.');const salt=crypto.getRandomValues(new Uint8Array(16));const hash=await demoPassword(p.password,salt);accounts.push({nombre:p.nombre,correo:p.correo.toLowerCase(),hash,salt:Array.from(salt),rol:'Mesero'});localStorage.setItem('aurea-demo-accounts',JSON.stringify(accounts));state.user={nombre:p.nombre,correo:p.correo,rol:'Mesero'}}else{const a=JSON.parse(localStorage.getItem('aurea-demo-accounts')||'[]').find(a=>a.correo===p.correo.toLowerCase());if(!a||a.hash!==await demoPassword(p.password,new Uint8Array(a.salt)))throw Error('Correo o contraseña incorrectos. Puedes usar los botones de acceso demo.');state.user={nombre:a.nombre,correo:a.correo,rol:a.rol}}state.data=JSON.parse(localStorage.getItem('aurea-demo-v1')||'null')||demoData()}else{const r=await api(state.register?'register':'login',p);state.user=r.user;state.data=await api('data')}state.page='inicio';state.register=false;render()}catch(error){const el=$('#login-error');if(el){el.textContent=error.message;el.classList.remove('hidden')}}finally{button.disabled=false}}});
async function demoPassword(password,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bytes=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:100000,hash:'SHA-256'},key,256);return [...new Uint8Array(bytes)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function start(){try{const session=await api('session');state.mode=session.mode;state.user=session.user;if(state.user)state.data=await api('data');render()}catch(error){$('#app').innerHTML=`<div class="login-panel" style="min-height:100vh"><div class="login-box">${brand()}<h2>No se pudo iniciar Áurea</h2><p>${esc(error.message)}</p><button class="btn primary" onclick="location.reload()">Reintentar</button></div></div>`}}
start();
